//! Query parser, matching `parseSearchQuery` in
//! `packages/core/src/search/search-query.ts` for the grammar it knows, plus
//! the Rust-only `type:`, `in:` and `modified:` filters.
//!
//! `CASES` is generated by `tests/goldens/search-query.mjs`.

use proptest::prelude::*;
use wf_core::search::query::{
    Clause, MAX_MODIFIED_DAYS, ParsedQuery, SearchKind, format_query, parse_clauses, parse_query,
};

/// (input, terms, phrases, exclude, kinds, paths, tags, text)
