fn owned(xs: &[&str]) -> Vec<String> {
    xs.iter().map(|x| (*x).to_owned()).collect()
}

fn kind_names(query: &ParsedQuery) -> Vec<&'static str> {
    query.kinds.iter().map(|kind| kind.as_str()).collect()
}

#[test]
fn every_case_matches_the_typescript() {
    for (input, terms, phrases, exclude, kinds, paths, tags, text) in CASES {
        let query = parse_query(input);
        assert_eq!(query.terms, owned(terms), "terms of {input:?}");
        assert_eq!(query.phrases, owned(phrases), "phrases of {input:?}");
        assert_eq!(query.exclude, owned(exclude), "exclude of {input:?}");
        assert_eq!(kind_names(&query), *kinds, "kinds of {input:?}");
        assert_eq!(query.paths, owned(paths), "paths of {input:?}");
        assert_eq!(query.tags, owned(tags), "tags of {input:?}");
        assert_eq!(query.text, *text, "text of {input:?}");
        assert_eq!(query.modified_within_days, None, "modified of {input:?}");
    }
}

#[test]
fn kinds_are_the_typescript_list_in_order() {
    let names: Vec<&str> = SearchKind::ALL.iter().map(|kind| kind.as_str()).collect();
    let expected = [
        "note",
        "paper",
        "list",
        "section",
        "experiment",
        "milestone",
        "log",
        "pdf",
        "annotation",
    ];
    assert_eq!(names, expected);
    for kind in SearchKind::ALL {
        assert_eq!(SearchKind::parse(kind.as_str()), Some(kind));
    }
    assert_eq!(SearchKind::parse("Note"), None);
    assert_eq!(SearchKind::parse("bogus"), None);
}

#[test]
fn clauses_keep_input_order() {
    let clauses = parse_clauses("b \"C d\" kind:note -X modified:1w a");
    assert_eq!(
        clauses,
        [
            Clause::Term("b".to_owned()),
            Clause::Phrase("c d".to_owned()),
            Clause::Kind(SearchKind::Note),
            Clause::Exclude("x".to_owned()),
            Clause::ModifiedWithinDays(7),
            Clause::Term("a".to_owned()),
        ]
    );
}

#[test]
fn type_and_in_are_aliases_of_kind_and_path() {
    let query = parse_query("TYPE:Note type:bogus in:Results IN: Type:pdf");
    assert_eq!(kind_names(&query), ["note", "pdf"]);
    assert_eq!(query.paths, ["results"]);
    assert!(query.terms.is_empty());
}

#[test]
fn modified_takes_a_count_and_a_unit() {
    let days = |input: &str| parse_query(input).modified_within_days;
    assert_eq!(days("modified:3d"), Some(3));
    assert_eq!(days("modified:2w"), Some(14));
    assert_eq!(days("modified:1m"), Some(30));
    assert_eq!(days("modified:1y"), Some(365));
    assert_eq!(days("MODIFIED:2W"), Some(14));
    assert_eq!(days("modified:\"5d\""), Some(5));
    assert_eq!(days("modified:007d"), Some(7));
    assert_eq!(days("modified:100y"), Some(MAX_MODIFIED_DAYS));
}

#[test]
fn the_smallest_modified_window_wins() {
    assert_eq!(
        parse_query("modified:2w modified:3d modified:1m").modified_within_days,
        Some(3)
    );
}

#[test]
fn invalid_modified_values_are_dropped_not_searched() {
    for input in [
        "modified:",
        "modified:0d",
        "modified:3",
        "modified:d",
        "modified:3x",
        "modified:3dd",
        "modified:-3d",
        "modified:+3d",
        "modified:3.5d",
        "modified:\u{663}d",
        "modified:101y",
        "modified:36501d",
        "modified:99999999999999999999d",
    ] {
        let query = parse_query(input);
        assert_eq!(query.modified_within_days, None, "{input:?}");
        assert!(query.terms.is_empty(), "{input:?} must not become a term");
        assert!(parse_clauses(input).is_empty(), "{input:?}");
    }
    assert_eq!(MAX_MODIFIED_DAYS, 36_500);
}

#[test]
fn filter_only_and_empty_match_the_typescript() {
    let only_filters = parse_query("kind:note modified:3d");
    assert!(only_filters.is_filter_only());
    assert!(!only_filters.is_empty());

    let modified_only = parse_query("modified:3d");
    assert!(!modified_only.is_empty());

    let exclusion_only = parse_query("-draft");
    assert!(exclusion_only.is_filter_only());
    assert!(!exclusion_only.is_empty());

    assert!(parse_query("  - \"\" kind:bogus ").is_empty());
    assert!(!parse_query("word").is_filter_only());
    assert_eq!(parse_query(""), ParsedQuery::from_clauses(&[]));
}

#[test]
fn format_prints_the_canonical_form() {
    let clauses =
        parse_clauses("Foo  \"Bar  Baz\" TYPE:pdf in:Sec tag:#X -\"no way\" -Old modified:2w");
    assert_eq!(
        format_query(&clauses),
        "foo \"bar  baz\" kind:pdf path:sec tag:x -\"no way\" -old modified:14d"
    );
    assert_eq!(format_query(&[]), "");
}

#[test]
fn format_quotes_values_that_would_reparse_differently() {
    for input in [
        "path:\"\"x\" path:x\"\" path:\"\"\"",
        "tag:# tag:##x tag:\"\"y\" tag:#\"",
        "-a\"\" -a\"b -\"a b\" --x",
        "a\"b x\" #hash",
    ] {
        let clauses = parse_clauses(input);
        let printed = format_query(&clauses);
        assert_eq!(
            parse_clauses(&printed),
            clauses,
            "{input:?} printed as {printed:?}"
        );
    }
}

#[test]
fn a_kelvin_sign_term_is_kept_as_a_term_like_the_typescript() {
    // The field match is ASCII-only, as in JS without the `u` flag, but
    // lowercasing turns U+212A into `k`. Its printed form therefore reparses
    // as a kind filter: the one known exception to the round trip.
    assert_eq!(
        parse_clauses("\u{212a}IND:note"),
        [Clause::Term("kind:note".to_owned())]
    );
}

/// Query-shaped text: fields, quotes, dashes, hashes, JS whitespace.
fn query_text() -> impl Strategy<Value = String> {
    r#"(kind:|path:|tag:|type:|in:|modified:|note|PDF|3d|2W|0d|-|"|#|:|a|B|é|Σ|İ| |  |\t|\x{a0}|\x{feff}|\x{85}){0,16}"#
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(256))]

    #[test]
    fn parsing_never_panics(input in any::<String>()) {
        let query = parse_query(&input);
        prop_assert!(query.text.len() <= input.len() * 3);
    }

    #[test]
    fn format_then_parse_gives_the_same_clauses(input in query_text()) {
        let clauses = parse_clauses(&input);
        let printed = format_query(&clauses);
        prop_assert_eq!(parse_clauses(&printed), clauses, "printed {:?}", printed);
    }
}
